import { performance } from 'node:perf_hooks';
import { expect } from 'chai';
import { hashPassword, verifyPassword } from '../src/modules/auth/password-hash';

// Generated by the previous @noble/hashes implementation with a fixed 16-byte salt.
const legacyHash = '$argon2id$v=19$m=65536,t=3,p=1$AAECAwQFBgcICQoLDA0ODw$4xpFPY9gvm2yNYpjy7WzgIqo4GsBH8azxfcdd00VGIY';

describe('password hashing', function () {
  this.timeout(10_000);

  it('hashes within one second at the configured cost', async () => {
    const start = performance.now();
    const stored = await hashPassword('correct horse battery');
    const elapsedMs = performance.now() - start;

    expect(stored).to.match(/^\$argon2id\$v=19\$m=65536,t=3,p=1\$/);
    expect(elapsedMs).to.be.lessThan(1_000);
    expect(await verifyPassword(stored, 'correct horse battery')).to.equal(true);
    expect(await verifyPassword(stored, 'wrong password')).to.equal(false);
  });

  it('verifies an existing @noble/hashes password', async () => {
    expect(await verifyPassword(legacyHash, 'IntegrationPassword!123')).to.equal(true);
    expect(await verifyPassword(legacyHash, 'wrong password')).to.equal(false);
    expect(await verifyPassword('$argon2id$v=19$m=999999,t=3,p=1$bad$bad', 'test')).to.equal(false);
  });
});
